using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using Frociart;
internal static class CodeTemplateCorpusTests {
 static string Hash(string value){using(var hash=SHA256.Create())return String.Concat(hash.ComputeHash(Encoding.UTF8.GetBytes(value)).Select(b=>b.ToString("x2")));}
 static string Mapping(FlowSourceText text){var b=new StringBuilder();foreach(var line in text.Lines){b.Append(line.Number).Append(',').Append(line.Start).Append(',').Append(line.Length);foreach(var origin in line.Origins)b.Append('|').Append(origin.FunctionId??"").Append(':').Append(origin.NodeId);b.Append('\n');}return Hash(b.ToString());}
 static int Main(string[] args){try{string root=args[0],fixtures=Path.Combine(root,"../javascript-source-qa/fixtures");Directory.CreateDirectory(Path.Combine(root,"cases"));var reports=new List<string>();int generated=0,rejected=0;
  foreach(string file in Directory.GetFiles(fixtures,"*.frociart").OrderBy(s=>s,StringComparer.Ordinal)){string name=Path.GetFileNameWithoutExtension(file);var document=DiagramIO.DecodeDocument(File.ReadAllBytes(file));var program=FlowSource.Compile(document);if(!program.CanGenerate){rejected++;continue;}byte[] before=DiagramIO.EncodeDocument(document);
   foreach(var target in FlowSourceTarget.All){var source=target.Generate(program);string comment=target==FlowSourceTarget.Python?"#":"//";var template=FlowCodeTemplate.Create("Personalizzato "+target.Name,target.Id,target.Extension,"Esegui con il compilatore del linguaggio",comment+" Titolo: {{ project.title | literal }}\n{# Il codice resta completo e mappato #}{{ source }}");var result=template.Generate(program,source);if(!result.Text.EndsWith(source.Text)||!before.SequenceEqual(DiagramIO.EncodeDocument(document)))throw new Exception("Source or project modified: "+name);reports.Add(name+"\t"+target.Id+"\t"+Hash(result.Text)+"\t"+Mapping(result));generated++;}
   var raw=FlowCodeTemplate.Create("Inventario","custom","txt","", "{{ program.title }}\n{% for scope in program.scopes %}{{ scope.key }} {{ scope.name }} {{ scope.returnType }} {{ scope.symbolNames | join:', ' }}\n{% for p in scope.parameters %}{{ p.identifier }} {{ p.type }} {{ p.array }} {{ p.reference }}\n{% endfor %}{% for b in scope.blocks %}{{ b.id }} {{ b.kind }} {{ b.text | literal }} {{ b.next }} {{ b.yes }} {{ b.no }} {{ b.fileReading }} {{ b.fileNewline }} {{ b.turtleDraw }} {{ b.turtleLeft }} {{ b.outputNewline }}\n{% endfor %}{% for n in scope.notes %}{{ n.text | literal }}\n{% endfor %}{% endfor %}");var rawResult=raw.Generate(program,null);reports.Add(name+"\tcustom\t"+Hash(rawResult.Text)+"\t"+Mapping(rawResult));generated++;
  }
  File.WriteAllLines(Path.Combine(root,"pc-corpus.tsv"),reports,new UTF8Encoding(false));
  var sample=FlowPseudocode.Decode("FUNZIONE doppio(x: INTERO) -> INTERO r\nr=x*2\nFINE FUNZIONE\nLEGGI x\nSE x>0 ALLORA\nSTAMPA doppio(x)\nALTRIMENTI\nSTAMPA \"Altro 🐢\"\nFINE SE");sample.Title="Titolo 🐢 {{ source }}";File.WriteAllBytes(Path.Combine(root,"sample.frociart"),DiagramIO.EncodeDocument(sample));var pgram=FlowSource.Compile(sample);
  string[] bodies={"{% for loop in program.scopes %}{{loop.index}}{% endfor %}","{{ program | count }}","{{ project.title }}","{{ 'a}}b' }}","{% raw %}{{ignored}}{% endraw %}","{% if true %}uno{% else %}due{% endif %}","{% for s in program.scopes %}{{loop.index}}/{{loop.length}} {{s.name}}\n{% endfor %}","{% macro e x %}{% if x.isNumber %}{{x.number|number}}{% else %}{% if x.isVariable %}{{x.identifier}}{% else %}({% render e x.children.0 %} {{x.text}} {% render e x.children.1 %}){% endif %}{% endif %}{% endmacro %}{% render e program.functions.0.blocks.1.writes.0.value %}","{{ program.main.symbolNames|join:', ' }}","{{ false|not }} {{ null|default:'vuoto' }} {{2|equals:2}}","{{program.main.blocks.1.text}}","{{ '\\u00e8 \\ud83d\\udc22' | upper }}","{{ 'é'|identifier}} {{'_u00e9'|identifier}}","{{ program.GetType }}","{% include 'file' %}","{{ 'x'|eval }}","{% if true %}","{% macro x a %}{% render x a %}{% endmacro %}{% render x program %}","{% require false|'Requisito' %}","{% require program.main.structured|not|'Grafo richiesto' %}"};
  var outcomes=new List<string>();int index=0;foreach(string body in bodies){string id="case"+index++;string definition="[Frociart Template]\nVersion = 1\nName = Caso\nBase = custom\nExtension = txt\nInstructions = \nCase Sensitive = true\n[Template]\n"+body;File.WriteAllText(Path.Combine(root,"cases",id+".frotemplate"),definition,new UTF8Encoding(false));try{var result=FlowCodeTemplate.Parse(definition).Generate(pgram,null);File.WriteAllText(Path.Combine(root,"cases",id+".txt"),result.Text,new UTF8Encoding(false));outcomes.Add(id+"\tPASS\t"+Hash(result.Text)+"\t"+Mapping(result));}catch(ArgumentException){outcomes.Add(id+"\tREJECT");}}
  File.WriteAllLines(Path.Combine(root,"pc-cases.tsv"),outcomes,new UTF8Encoding(false));Console.WriteLine("TEMPLATE_CORPUS_PC PASS generated="+generated+" invalid="+rejected+" parserCases="+outcomes.Count);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
